        // The bug is that netInputAmount += royaltyFeeAmount is missing. 
        // Even with royaltyFeeAmount=0, the behavior is same. So we need royaltyFeeAmount > 0.
        // Let's set up a royalty registry that returns an address supporting IERC2981.

        // Deploy a mock royalty registry that returns a mock royalty lookup
        MockRoyaltyRegistry registry = new MockRoyaltyRegistry();
        MockRoyaltyLookup lookup = new MockRoyaltyLookup();
        registry.setLookup(address(nft), address(lookup));
        lookup.setRoyaltyInfo(1, address(0x123), 0.1 ether);

        // But c's constructor takes factory, royaltyRegistry, stolenNftOracle
