        // Reference expected: netInputAmount (without royaltyFee) = 112222222222222222222
        uint256 expectedBalance = 112222222222222222222;
        assertEq(baseToken.balanceOf(address(c2)), expectedBalance);
    }
}

// Helper contracts to make the test work
contract TestERC721 {
    mapping(uint256 => address) public ownerOf;
    mapping(uint256 => address) public getApproved;
    mapping(address => mapping(address => bool)) public isApprovedForAll;

    function mint(address to, uint256 id) external {
        ownerOf[id] = to;
    }

    function approve(address spender, uint256 id) external {
        getApproved[id] = spender;
    }

    function safeTransferFrom(address from, address to, uint256 id) external {
        require(ownerOf[id] == from, "wrong from");
        ownerOf[id] = to;
    }

    function transferFrom(address from, address to, uint256 id) external {
        require(ownerOf[id] == from, "wrong from");
        ownerOf[id] = to;
    }
}

contract TestERC20 {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    uint8 public decimals = 18;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        if (allowance[from][msg.sender] != type(uint256).max) {
            allowance[from][msg.sender] -= amount;
        }
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

contract MockRoyaltyRegistry {
    mapping(address => address) public lookup;

    function setLookup(address token, address lookupAddress) external {
        lookup[token] = lookupAddress;
    }

    function getRoyaltyLookupAddress(address token) external view returns (address) {
        return lookup[token];
    }
}

contract MockRoyaltyLookup {
    mapping(uint256 => uint256) public royaltyFees;
    mapping(uint256 => address) public recipients;

    function setRoyaltyInfo(uint256 tokenId, address recipient, uint256 fee) external {
        royaltyFees[tokenId] = fee;
        recipients[tokenId] = recipient;
    }

    function supportsInterface(bytes4 interfaceId) external pure returns (bool) {
        return interfaceId == 0x2f552a0b; // IERC2981
    }

    function royaltyInfo(uint256 tokenId, uint256 salePrice) external view returns (address, uint256) {
        return (recipients[tokenId], royaltyFees[tokenId]);
    }
}

